from pathlib import Path
import base64,zipfile,io,hashlib,subprocess,sys
payload=base64.b64decode('')
assert hashlib.sha256(payload).hexdigest()=='012e7c6a04249bff1139027b5a469c598c8cad56aa82ef1fefcfcdb4a12a5507'
root=Path('/kaggle/working/quality_source');root.mkdir(exist_ok=False)
with zipfile.ZipFile(io.BytesIO(payload)) as z:
 for i in z.infolist():assert (root/i.filename).resolve().is_relative_to(root.resolve())
 z.extractall(root)
p=subprocess.run([sys.executable,'-X','utf8','run_checks.py'],cwd=root,capture_output=True,text=True)
print(p.stdout)
assert p.returncode==0,'CPU tests failed'
